    const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
    useEffect(() => {
        const list = timers.current;
        return () => list.forEach(clearTimeout);
    }, []);
    const run = () => {
        if (state !== "idle")
            return;
        setState("loading");
        timers.current.push(setTimeout(() => setState("success"), 1400));
        timers.current.push(setTimeout(() => setState("idle"), 2900));
    };
    return (<StatefulButton state={state} variant={(__HUEMO_PROP_variant__ as string) as ButtonVariant} loadingText={loadingText} successText={successText} onClick={run}>
      {"Save changes"}
    </StatefulButton>);
}

